// Differential runner: compare /output/test5.mjs against the reference executable.
// Usage: node diff.mjs <cases-or-observed.json> [...more files]
// Accepts either raw case files ({a,b}) or observed files (extra fields ignored).
// Compares stdout byte-for-byte and exit-code-zero-ness (nonzero exit = "error" class).
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test5_executable';
const JS = '/output/test5.mjs';

let cases = [];
for (const f of process.argv.slice(2)) {
  const parsed = JSON.parse(readFileSync(f, 'utf8'));
  for (const c of parsed) cases.push({ ...c, _src: f });
}

const run = (cmd, args, c) => {
  const argv = [];
  if (c.argv) argv.push(...c.argv);
  else {
    if (c.a !== undefined) argv.push('--a', c.a);
    if (c.b !== undefined) argv.push('--b', c.b);
  }
  const r = spawnSync(cmd, [...args, ...argv], { encoding: 'utf8', timeout: 30000 });
  return { stdout: r.stdout ?? '', code: r.status, stderr: r.stderr ?? '' };
};

let pass = 0;
const fails = [];
for (const c of cases) {
  const py = run(EXE, [], c);
  const js = run('node', [JS], c);
  const pyErr = py.code !== 0;
  const jsErr = js.code !== 0;
  const ok = pyErr ? jsErr : !jsErr && py.stdout === js.stdout;
  if (ok) pass++;
  else
    fails.push({
      a: c.a,
      b: c.b,
      argv: c.argv,
      note: c.note,
      py: pyErr ? `EXIT${py.code}` : JSON.stringify(py.stdout),
      js: jsErr ? `EXIT${js.code}: ${js.stderr.trim().split('\n').pop()?.slice(0, 160)}` : JSON.stringify(js.stdout),
      src: c._src,
    });
}

for (const f of fails) {
  console.log(`MISMATCH a=${String(f.a).slice(0, 90)}\n         b=${String(f.b).slice(0, 160)}${f.argv ? '\n         argv=' + JSON.stringify(f.argv) : ''}`);
  console.log(`         py=${f.py}   js=${f.js}${f.note ? '   # ' + f.note : ''}`);
}
console.log(`\n${pass}/${cases.length} match, ${fails.length} mismatches`);
process.exit(fails.length ? 1 : 0);

